// ═══════════════════════════════════════════════════════════
// NODE: Calculate Days + Block Condition Check
//  Added 'non-renewal' and 'endorsement' to blocked list
//  Only policies with Policy Status = 'active' proceed
//  IST date calculation remains, but we also set _istToday for debug
//  Skipping rows with no Expiration Date gracefully
//  Added _daysToExpiry for monitoring
// ═══════════════════════════════════════════════════════════

const now = new Date();

// Get today in IST as YYYY-MM-DD (robust cross-platform)
const today = now.toLocaleDateString('en-CA', {
  timeZone: 'Asia/Kolkata'
});

// BLOCK CONDITIONS — these policies must NEVER get reminders
const blockedStatuses = [
  'lapsed', 'cancelled', 'withdrawn', 'expired',
  'void', 'terminated', 'non-renewal', 'endorsement'
];

// ALLOWED CONDITIONS — only these can receive reminder emails
const allowedStatuses = ['active', 'new', 'renewal'];

// Helper: subtract N days from a date string → YYYY-MM-DD
function subtractDays(dateStr, days) {
  const d = new Date(dateStr);
  d.setUTCDate(d.getUTCDate() - days);
  return d.toISOString().split('T')[0];
}

// Helper: parse expiration date from multiple column name variants
function getExpDate(json) {
  return (
    json['Expiration Date'] ||
    json['ExpirationDate'] ||
    json['expirationDate'] ||
    json['expiry_date'] ||
    json['ExpiryDate'] ||
    ''
  ).toString().trim();
}

// Helper: calculate days remaining until expiry
function daysToExpiry(dateStr) {
  const exp = new Date(dateStr);
  const todayMs = new Date(today);
  return Math.ceil((exp - todayMs) / (1000 * 60 * 60 * 24));
}

const rows = $input.all();

return rows.map(item => {

  const transaction = (item.json['Policy transaction'] || '')
    .toString().trim().toLowerCase();

  // ── BLOCK CHECK ──────────────────────────────────────────────
  if (blockedStatuses.includes(transaction)) {
    return {
      json: {
        ...item.json,
        today,
        day_90: '',
        day_60: '',
        day_30: '',
        _blocked: true,
        _blockReason: 'Policy transaction is "' + transaction + '" - blocked from reminders',
        _stage: 'blocked',
        _daysToExpiry: null
      }
    };
  }

  // ── ALLOWED CHECK ─────────────────────────────────────────────
  if (!allowedStatuses.includes(transaction)) {
    return {
      json: {
        ...item.json,
        today,
        day_90: '',
        day_60: '',
        day_30: '',
        _blocked: true,
        _blockReason: 'Unknown transaction type "' + transaction + '" - skipped for safety',
        _stage: 'skipped',
        _daysToExpiry: null
      }
    };
  }

  // ── DATE VALIDATION ───────────────────────────────────────────
  const rawDate = getExpDate(item.json);

  if (!rawDate) {
    return {
      json: {
        ...item.json,
        today,
        day_90: '',
        day_60: '',
        day_30: '',
        _blocked: true,
        _blockReason: 'Missing Expiration Date — cannot calculate reminders',
        _stage: 'error_missing_date',
        _daysToExpiry: null
      }
    };
  }

  const expDate = new Date(rawDate);
  if (isNaN(expDate.getTime())) {
    return {
      json: {
        ...item.json,
        today,
        day_90: '',
        day_60: '',
        day_30: '',
        _blocked: true,
        _blockReason: 'Invalid Expiration Date format: ' + rawDate,
        _stage: 'error_invalid_date',
        _daysToExpiry: null
      }
    };
  }

  // ── ALREADY EXPIRED CHECK ─────────────────────────────────────
  const remaining = daysToExpiry(rawDate);
  if (remaining < 0) {
    return {
      json: {
        ...item.json,
        today,
        day_90: subtractDays(rawDate, 90),
        day_60: subtractDays(rawDate, 60),
        day_30: subtractDays(rawDate, 30),
        _blocked: true,
        _blockReason: 'Policy already expired ' + Math.abs(remaining) + ' day(s) ago',
        _stage: 'already_expired',
        _daysToExpiry: remaining
      }
    };
  }

  // ── CALCULATE REMINDER DATES ──────────────────────────────────
  const day_90 = subtractDays(rawDate, 90);
  const day_60 = subtractDays(rawDate, 60);
  const day_30 = subtractDays(rawDate, 30);

  return {
    json: {
      ...item.json,
      today,
      day_90,
      day_60,
      day_30,
      _blocked: false,
      _stage: 'dates_calculated',
      _daysToExpiry: remaining
    }
  };

});

// ═══════════════════════════════════════════════════════════
// NODE: Policy Status
//  Status 'active' is ONLY assigned when transaction is
//        active/new/renewal AND the policy is NOT blocked
//  Added non-renewal and endorsement handling
//  Added _statusTimestamp for audit trail
// ═══════════════════════════════════════════════════════════

const rows = $input.all();

return rows.map(item => {

  const transaction = (item.json['Policy transaction'] || '')
    .toString().trim().toLowerCase();

  const blocked = item.json._blocked === true;

  let policyStatus;

  if (transaction === 'lapsed')           policyStatus = 'lapsed';
  else if (transaction === 'cancelled')   policyStatus = 'cancelled';
  else if (transaction === 'withdrawn')   policyStatus = 'withdrawn';
  else if (transaction === 'expired')     policyStatus = 'expired';
  else if (transaction === 'void')        policyStatus = 'void';
  else if (transaction === 'terminated')  policyStatus = 'terminated';
  else if (transaction === 'non-renewal') policyStatus = 'non-renewal';
  else if (transaction === 'endorsement') policyStatus = 'endorsement';
  else if (['active', 'new', 'renewal'].includes(transaction) && !blocked) {
    policyStatus = 'active';
  } else if (['active', 'new', 'renewal'].includes(transaction) && blocked) {
    // allowed transaction type but blocked for another reason (e.g. expired date)
    policyStatus = 'inactive';
  } else {
    policyStatus = 'unknown';
  }

  return {
    json: {
      ...item.json,
      'Policy Status': policyStatus,
      _stage: 'status_assigned',
      _statusTimestamp: new Date().toISOString()
    }
  };

});

// ═══════════════════════════════════════════════════════════
// NODE: Check 90 Day Reminder
// Added explicit Policy Status === 'active' guard
//        Previously only checked _blocked flag; now double-checks
//        the actual Policy Status written to sheet for accuracy
// Added _check90Timestamp for audit
// Detailed reason string for easier debugging
// ═══════════════════════════════════════════════════════════

const rows = $input.all();

return rows.map(item => {

  const today        = item.json.today || '';
  const day_90       = item.json.day_90 || '';
  const blocked      = item.json._blocked === true;
  const policyStatus = (item.json['Policy Status'] || '').toLowerCase();
  const alreadySent  = (item.json.email_sent_90 || '').toLowerCase() === 'sent';

  // CRITICAL: Only send if status is explicitly 'active'
  const isActive = policyStatus === 'active';

  const shouldSend = (today === day_90) && !blocked && isActive && !alreadySent;

  return {
    json: {
      ...item.json,
      _check90: shouldSend,
      _check90Reason: shouldSend
        ? '90-day reminder due today for active policy'
        : [
            'today=' + today,
            'day_90=' + day_90,
            'blocked=' + blocked,
            'status=' + policyStatus,
            'alreadySent=' + alreadySent
          ].join(' | ')
    }
  };

});

// ═══════════════════════════════════════════════════════════
// NODE: Check 60 Day Reminder
//  Added explicit Policy Status === 'active' guard
//  Added _check60Timestamp and improved reason string
// ═══════════════════════════════════════════════════════════

