        : [
            'today=' + today,
            'day_60=' + day_60,
            'blocked=' + blocked,
            'status=' + policyStatus,
            'alreadySent=' + alreadySent
          ].join(' | ')
    }
  };

});

// ═══════════════════════════════════════════════════════════
// NODE: Check 30 Day Reminder
//  Added explicit Policy Status === 'active' guard
//  Added improved reason string for debugging
// ═══════════════════════════════════════════════════════════

const rows = $input.all();

return rows.map(item => {

  const today        = item.json.today || '';
  const day_30       = item.json.day_30 || '';
  const blocked      = item.json._blocked === true;
  const policyStatus = (item.json['Policy Status'] || '').toLowerCase();
  const alreadySent  = (item.json.email_sent_30 || '').toLowerCase() === 'sent';

  const isActive = policyStatus === 'active';

  const shouldSend = (today === day_30) && !blocked && isActive && !alreadySent;

  return {
